package pgm

import groovy.json.JsonSlurper

import javax.lang.model.SourceVersion

class BindingEmitter {
    private static final String HEADER = '''\
// SPDX-FileCopyrightText: Contributors to the Power Grid Model project <powergridmodel@lfenergy.org>
// SPDX-License-Identifier: MPL-2.0
// Generated by the PGM binding generator.

package org.lfenergy.pgm;

import java.lang.foreign.*;
import java.lang.invoke.*;

'''
    private static final Map<String, List<String>> TYPES = [
        'void': ['void', '', ''],
        'char': ['byte', 'OfByte', 'C_CHAR'],
        'int': ['int', 'OfInt', 'C_INT'],
        'double': ['double', 'OfDouble', 'C_DOUBLE'],
        'pointer': ['MemorySegment', 'AddressLayout', 'C_POINTER'],
        'size_t': ['long', 'OfLong', 'size_t'],
        'int8_t': ['byte', 'OfByte', 'ValueLayout.JAVA_BYTE'],
        'uint8_t': ['byte', 'OfByte', 'ValueLayout.JAVA_BYTE'],
        'int16_t': ['short', 'OfShort', 'ValueLayout.JAVA_SHORT'],
        'uint16_t': ['short', 'OfShort', 'ValueLayout.JAVA_SHORT'],
        'int32_t': ['int', 'OfInt', 'ValueLayout.JAVA_INT'],
        'uint32_t': ['int', 'OfInt', 'ValueLayout.JAVA_INT'],
        'int64_t': ['long', 'OfLong', 'ValueLayout.JAVA_LONG'],
        'uint64_t': ['long', 'OfLong', 'ValueLayout.JAVA_LONG'],
    ]

    static void emit(File inventory, File output) {
        def declarations = new JsonSlurper().parse(inventory).declarations.sort { it.name }
        Map<String, String> files = [:]
        def api = new StringBuilder(HEADER + '''\
/** Low-level bindings to the Power Grid Model C API. */
public class PowerGridModelC {
    PowerGridModelC() {}

    static final Linker LINKER = Linker.nativeLinker();
    private static final SymbolLookup SYMBOLS = SymbolLookup.loaderLookup();

    public static final ValueLayout.OfBoolean C_BOOL = (ValueLayout.OfBoolean) canonical("bool");
    public static final ValueLayout.OfByte C_CHAR = (ValueLayout.OfByte) canonical("char");
    public static final ValueLayout.OfShort C_SHORT = (ValueLayout.OfShort) canonical("short");
    public static final ValueLayout.OfInt C_INT = (ValueLayout.OfInt) canonical("int");
    public static final ValueLayout.OfLong C_LONG_LONG = (ValueLayout.OfLong) canonical("long long");
    public static final ValueLayout.OfFloat C_FLOAT = (ValueLayout.OfFloat) canonical("float");
    public static final ValueLayout.OfDouble C_DOUBLE = (ValueLayout.OfDouble) canonical("double");
    public static final ValueLayout.OfLong size_t = (ValueLayout.OfLong) canonical("size_t");
    public static final AddressLayout C_POINTER = ((AddressLayout) canonical("void*"))
        .withTargetLayout(MemoryLayout.sequenceLayout(Long.MAX_VALUE, C_CHAR));

    private static MemoryLayout canonical(String name) {
        var layout = LINKER.canonicalLayouts().get(name);
        if (layout == null) {
            throw new IllegalStateException("Missing native linker layout: " + name);
        }
        return layout;
    }

    private static MemorySegment symbol(String name) {
        return SYMBOLS.find(name).orElseThrow(() -> new UnsatisfiedLinkError(
            "Cannot resolve PGM symbol " + name + "; load the matching PGM library before invoking it"));
    }
''')
        declarations.each { declaration ->
            String name = declaration.name
            if (!SourceVersion.isIdentifier(name) || SourceVersion.isKeyword(name) ||
                    name in ['record', 'var', 'yield', 'sealed', 'permits', 'PowerGridModelC']) {
                throw new IllegalArgumentException("${declaration.location}: cannot expose ${name} as a Java binding")
            }
            Map shape = declaration.shape
            switch (shape.kind) {
                case 'function':
                    api.append(function(name, shape))
                    break
                case 'global':
                    api.append(global(name, shape.type.const))
                    break
                case 'constant':
                    api.append("\n    public static int ${name}() { return ${shape.value}; }\n")
                    break
                case 'typedef':
                    Map type = shape.type
                    if (type.kind == 'pointer' && type.pointee.kind == 'function') {
                        files["${name}.java".toString()] = callback(name, type.pointee)
                    } else if (type.kind != 'opaque' && type.kind != 'void') {
                        def (_, layoutType, layout) = TYPES[type.kind]
                        String javaType = layoutType == 'AddressLayout' ? layoutType : "ValueLayout.${layoutType}"
                        api.append("\n    public static final ${javaType} ${name} = ${layout};\n")
                    }
                    break
                default:
                    throw new IllegalArgumentException("${declaration.location}: unknown declaration kind: ${shape.kind}")
            }
        }
        files['PowerGridModelC.java'] = api.append('}\n').toString()
        File pkg = new File(output, 'org/lfenergy/pgm')
        pkg.mkdirs()
        files.each { name, contents -> new File(pkg, name).setText(contents.replace('\r\n', '\n'), 'UTF-8') }
    }

    private static String descriptor(Map shape, String prefix = '') {
        def args = shape.args.collect { layout(it, prefix) }
        if (shape.result.kind == 'void') {
            return "FunctionDescriptor.ofVoid(${args.join(', ')})"
        }
        args.add(0, layout(shape.result, prefix))
        return "FunctionDescriptor.of(${args.join(', ')})"
    }

    private static String layout(Map type, String prefix) {
        String expression = TYPES[type.kind][2]
        return expression.startsWith('ValueLayout.') ? expression : prefix + expression
    }

    private static String parameters(Map shape) {
        shape.args.withIndex().collect { type, i -> "${TYPES[type.kind][0]} arg${i}" }.join(', ')
    }

    private static String invocation(Map shape, String handle, List<String> leading = []) {
        String returned = TYPES[shape.result.kind][0]
        String cast = returned == 'void' ? '' : "return (${returned}) "
        def args = leading + shape.args.indices.collect { "arg${it}" }
        return """\
        try {
            ${cast}${handle}.invokeExact(${args.join(', ')});
        } catch (RuntimeException | Error ex) {
            throw ex;
        } catch (Throwable ex) {
            throw new AssertionError("Unexpected exception invoking a PGM binding", ex);
        }
"""
    }

    private static String function(String name, Map shape) {
        """\

    private static final class ${name}\$Descriptor {
        static final FunctionDescriptor VALUE = ${descriptor(shape)};
    }

    private static final class ${name}\$Downcall {
        static final MemorySegment ADDRESS = symbol("${name}");
        static final MethodHandle HANDLE = LINKER.downcallHandle(ADDRESS, ${name}\$descriptor());
    }

    public static FunctionDescriptor ${name}\$descriptor() { return ${name}\$Descriptor.VALUE; }
    public static MemorySegment ${name}\$address() { return ${name}\$Downcall.ADDRESS; }
    public static MethodHandle ${name}\$handle() { return ${name}\$Downcall.HANDLE; }

    public static ${TYPES[shape.result.kind][0]} ${name}(${parameters(shape)}) {
${invocation(shape, "${name}\$Downcall.HANDLE")}    }
"""
    }

    private static String global(String name, boolean constant) {
        String readOnly = constant ? '.asReadOnly()' : ''
        String setter = constant ? '' : """
    public static void ${name}(MemorySegment value) { ${name}\$segment().set(C_POINTER, 0, value); }
"""
        """\

    private static final class ${name}\$Storage {
        static final MemorySegment SLOT = symbol("${name}").reinterpret(C_POINTER.byteSize())${readOnly};
    }

    public static AddressLayout ${name}\$layout() { return C_POINTER; }
    public static MemorySegment ${name}\$segment() { return ${name}\$Storage.SLOT; }
    public static MemorySegment ${name}() { return ${name}\$segment().get(C_POINTER, 0); }
${setter}"""
    }

    private static String callback(String name, Map shape) {
        String returned = TYPES[shape.result.kind][0]
        String args = parameters(shape)
        """\
${HEADER}/** Native callback declared as {@code ${name}}. */
public final class ${name} {
    private ${name}() {}

    @FunctionalInterface
    public interface Function {
        ${returned} apply(${args});
    }

    private static final FunctionDescriptor DESCRIPTOR = ${descriptor(shape, 'PowerGridModelC.')};
    private static final MethodHandle DOWNCALL = PowerGridModelC.LINKER.downcallHandle(DESCRIPTOR);

    private static MethodHandle upcall() {
        try {
            return MethodHandles.lookup().findVirtual(Function.class, "apply", DESCRIPTOR.toMethodType());
        } catch (ReflectiveOperationException ex) {
            throw new AssertionError("Cannot find ${name}.Function.apply", ex);
        }
    }

    public static FunctionDescriptor descriptor() { return DESCRIPTOR; }

    /** The stub is valid while {@code arena} remains open. The callback must not throw. */
    public static MemorySegment allocate(Function function, Arena arena) {
        return PowerGridModelC.LINKER.upcallStub(upcall().bindTo(function), DESCRIPTOR, arena);
    }

    public static ${returned} invoke(MemorySegment pointer${args ? ', ' + args : ''}) {
${invocation(shape, 'DOWNCALL', ['pointer'])}    }
}
"""
    }
}
